<?php use Hospital\Models\Appointment; ?>
<div class="page-heading"><div><p class="eyebrow">Your care calendar</p><h1>My appointments</h1></div><a class="button" href="/patient">Find a doctor</a></div>
<?php foreach (Appointment::STATUSES as $status): $group = array_filter($appointments, static fn ($item) => $item['status'] === $status); ?>
<section class="appointment-group" data-status-group="<?= $e($status) ?>"><h2><?= $e($status) ?></h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Doctor</th><th>Date / time</th><th>Reason</th><th>Status</th><th>Action</th></tr></thead><tbody data-group-body>
<?php foreach ($group as $item): ?><tr data-appointment-id="<?= (int) $item['id'] ?>"><td>#<?= (int) $item['id'] ?></td><td><?= $e($item['doctor_name']) ?><br><small><?= $e($item['specialization']) ?></small></td><td><?= $e($item['appointment_date']) ?><br><?= $e(substr($item['appointment_time'],0,5)) ?></td><td><?= $e($item['reason']) ?></td><td><span class="badge <?= strtolower($status) ?>" data-status-badge><?= $e($status) ?></span></td><td><?php if ($status === 'Pending'): ?><button class="danger" data-cancel-appointment="<?= (int) $item['id'] ?>">Cancel</button><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?>
<tr data-empty-row <?= $group ? 'hidden' : '' ?>><td colspan="6">No <?= $e(strtolower($status)) ?> appointments.</td></tr></tbody></table></div></section><?php endforeach; ?>
